#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* lltoa(long long num) {
    char buffer[32];
    snprintf(buffer, sizeof(buffer), "%lld", num);
    char* str = (char*)malloc(strlen(buffer) + 1);
    strcpy(str, buffer);
    return str;
}

char** fibs_fizz_buzz(int n) {
    long long* fib = (long long*)malloc(sizeof(long long) * n);
    char** result = (char**)malloc(sizeof(char*) * n);

    fib[0] = 1;
    if (n > 1) fib[1] = 1;
    for (int i = 2; i < n; i++) {
        fib[i] = fib[i - 1] + fib[i - 2];
    }

    for (int i = 0; i < n; i++) {
        if (fib[i] % 15 == 0) {
            result[i] = strdup("FizzBuzz");
        } else if (fib[i] % 3 == 0) {
            result[i] = strdup("Fizz");
        } else if (fib[i] % 5 == 0) {
            result[i] = strdup("Buzz");
        } else {
            result[i] = lltoa(fib[i]);
        }
    }

    free(fib);
    return result;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int can_build(const char *hand, const char *recipe) {
    int need[256] = {0}, have[256] = {0};
    for (int i = 0; recipe[i]; i++) need[(unsigned char)recipe[i]]++;
    for (int i = 0; hand[i]; i++) have[(unsigned char)hand[i]]++;
    for (int i = 0; i < 256; i++) {
        if (need[i] > have[i]) return 0;
    }
    return 1;
}

char** build_or_buy(const char *hand, int *returnSize) {
    const char *names[]   = {"road", "settlement", "city", "development"};
    const char *recipes[] = {"bw", "bwsg", "ooogg", "osg"};
    int count = 0;
    char **result = malloc(4 * sizeof(char*));

    for (int i = 0; i < 4; i++) {
        if (can_build(hand, recipes[i])) {
            result[count] = strdup(names[i]);
            count++;
        }
    }

    *returnSize = count;
    return result;
}

#include <stdio.h>
#include <limits.h>

int maxScore(int* cardPoints, int cardPointsSize, int k) {
    long long total = 0;
    for (int i = 0; i < cardPointsSize; i++) total += cardPoints[i];

    if (k == cardPointsSize) return (int)total;

    int window = cardPointsSize - k;
    long long cur = 0;
    for (int i = 0; i < window; i++) cur += cardPoints[i];
    long long minSum = cur;

    for (int i = window; i < cardPointsSize; i++) {
        cur += cardPoints[i] - cardPoints[i - window];
        if (cur < minSum) minSum = cur;
    }

    return (int)(total - minSum);
}

#include <stdio.h>

int clumsy(int N) {
    int stack[10005];
    int top = -1;

    stack[++top] = N; // 第一个数直接入栈
    N--;
    int op = 0; // 0:*, 1:/, 2:+, 3:-

    while (N > 0) {
        if (op == 0) {
            stack[top] = stack[top] * N;
        } else if (op == 1) {
            stack[top] = stack[top] / N;
        } else if (op == 2) {
            stack[++top] = N;
        } else {
            stack[++top] = -N;
        }
        op = (op + 1) % 4;
        N--;
    }

    int ans = 0;
    for (int i = 0; i <= top; i++) ans += stack[i];
    return ans;
}
